package com.alzhefi
import android.content.Intent
import android.os.Build
import android.util.Base64
import org.json.JSONObject
import com.facebook.react.bridge.*
class LocationTrackingModule(private val context:ReactApplicationContext):ReactContextBaseJavaModule(context){
 override fun getName()="LocationTracking"
 @ReactMethod fun start(owner:String,role:String,token:String,promise:Promise){try{if(context.currentActivity==null||context.lifecycleState!=com.facebook.react.common.LifecycleState.RESUMED){promise.reject("NOT_VISIBLE","Open AlzheFi to start tracking.");return};if(owner.isBlank()||token.isBlank()||role !in listOf("patient","caregiver")){promise.reject("INVALID_SESSION","Check the signed-in account.");return};val claims=JSONObject(String(Base64.decode(token.split(".")[1],Base64.URL_SAFE or Base64.NO_WRAP or Base64.NO_PADDING)));if(claims.optString("id")!=owner){promise.reject("ACCOUNT_CHANGED","Signed-in account changed. Open AlzheFi again.");return};LocationTrackingService.epoch++;TrackingStore.save(context,owner,role,token);val i=Intent(context,LocationTrackingService::class.java);if(Build.VERSION.SDK_INT>=26)context.startForegroundService(i)else context.startService(i);promise.resolve(true)}catch(_:Exception){TrackingStore.clear(context);promise.reject("START_FAILED","Native tracking could not start.")}}
 @ReactMethod fun stop(promise:Promise){LocationTrackingService.epoch++;TrackingStore.clear(context);context.stopService(Intent(context,LocationTrackingService::class.java));promise.resolve(true)}

 private fun photoFile(owner:String,plan:String):java.io.File{require(owner.matches(Regex("[a-fA-F0-9]{24}"))&&plan.matches(Regex("[a-fA-F0-9]{24}")));return java.io.File(context.noBackupFilesDir,"medicine-photo-"+owner+"-"+plan)}
 @ReactMethod fun saveMedicationPhoto(owner:String,plan:String,data:String,promise:Promise){try{val file=photoFile(owner,plan);if(data.isEmpty()){file.delete();promise.resolve(true);return};require(data.length<=700100&&data.startsWith("data:image/"));val cipher=javax.crypto.Cipher.getInstance("AES/GCM/NoPadding");cipher.init(javax.crypto.Cipher.ENCRYPT_MODE,TrackingStore.key());file.writeBytes(cipher.iv+cipher.doFinal(data.toByteArray()));promise.resolve(true)}catch(_:Exception){promise.reject("PHOTO_FAILED","Optional local photo could not be saved.")}}
 @ReactMethod fun loadMedicationPhoto(owner:String,plan:String,promise:Promise){try{val file=photoFile(owner,plan);if(!file.exists()){promise.resolve("");return};val bytes=file.readBytes();val cipher=javax.crypto.Cipher.getInstance("AES/GCM/NoPadding");cipher.init(javax.crypto.Cipher.DECRYPT_MODE,TrackingStore.key(),javax.crypto.spec.GCMParameterSpec(128,bytes.copyOfRange(0,12)));promise.resolve(String(cipher.doFinal(bytes.copyOfRange(12,bytes.size))))}catch(_:Exception){promise.resolve("")}}
 @ReactMethod fun status(promise:Promise){val now=System.currentTimeMillis();val map=Arguments.createMap();map.putBoolean("running",LocationTrackingService.running);map.putDouble("lastFixReceived",LocationTrackingService.lastFixReceived.toDouble());map.putDouble("lastFixRecorded",LocationTrackingService.lastFixRecorded.toDouble());map.putDouble("lastSent",LocationTrackingService.lastSent.toDouble());val age=now-LocationTrackingService.lastFixReceived;val sentAge=now-LocationTrackingService.lastSent;map.putString("issue",when{!LocationTrackingService.running->"Tracking is not running. Open this screen to check sharing and restart.";LocationTrackingService.lastFixReceived==0L->LocationTrackingService.issue;age>=60000->"No new native GPS callback for "+age/1000+"s. Tracking may be interrupted.";LocationTrackingService.issue.isNotBlank()->LocationTrackingService.issue;else->"Native GPS callback "+age/1000+"s ago. Last successful send "+sentAge/1000+"s ago."});promise.resolve(map)}
}
